defmodule JoobQ.TelemetryFamiliesTest do
  use ExUnit.Case, async: true

  @families [:schedule, :rate_limit, :batch, :workflow]
  @suffixes [:start, :stop, :exception]
  @events for family <- @families, suffix <- @suffixes, do: [:joobq, family, suffix]
  @batch "0b9f6f9e-1c2d-4e5f-8a9b-0c1d2e3f4a5b"

  def forward(event, _measurements, %{instance: instance} = metadata, {pid, instance}),
    do: send(pid, {:event, event, metadata})

  def forward(_event, _measurements, _metadata, _other), do: :ok

  setup do
    bypass = Bypass.open()
    name = :"joobq_#{System.unique_integer([:positive])}"
    start_supervised!({JoobQ, name: name, url: "http://localhost:#{bypass.port}", token: "t0ken"})
    id = "families-#{name}"
    :ok = :telemetry.attach_many(id, @events, &__MODULE__.forward/4, {self(), name})
    on_exit(fn -> :telemetry.detach(id) end)
    {:ok, bypass: bypass, name: name}
  end

  defp answer(bypass, path, body) do
    Bypass.expect_once(bypass, "POST", "/api/v1/sdk" <> path, fn conn ->
      Plug.Conn.resp(conn, 200, Jason.encode!(body))
    end)
  end

  defp span(family) do
    assert_received {:event, [:joobq, ^family, :start], start}
    assert_received {:event, [:joobq, ^family, :stop], stop}
    {start, stop}
  end

  test "start and stop carry exactly the documented metadata", %{bypass: bypass, name: name} do
    answer(bypass, "/schedules", %{id: "s", name: "s", kind: "job", created: true})
    answer(bypass, "/rate-limit", %{allowed: true, retry_after_ms: 0})
    answer(bypass, "/batches", %{batch_id: @batch, total: 1, jobs: []})
    answer(bypass, "/workflows/run-secret-1/signal", %{id: "run-secret-1", accepted: true})

    payload = %{"v" => "payload-secret"}

    {:ok, _schedule} =
      JoobQ.register_schedule("nightly", "mail", "digest", name: name, every: "1 hour")

    {:ok, _slot} = JoobQ.rate_limit("tenant-secret", 5, 1_000, name: name)
    {:ok, _batch} = JoobQ.create_batch([{"mail", "send", payload}], name: name)
    {:ok, _signal} = JoobQ.signal_workflow("run-secret-1", "approve", payload, name: name)

    assert {start, stop} = span(:schedule)
    assert start == %{instance: name, schedule: "nightly", queue: "mail", job_type: "digest"}
    assert stop == Map.merge(start, %{result: :ok, reason: nil})

    assert {start, stop} = span(:rate_limit)
    assert start == %{instance: name, limit: 5, period_ms: 1_000}
    assert stop == Map.merge(start, %{result: :ok, reason: nil, allowed: true})

    assert {start, stop} = span(:batch)
    assert start == %{instance: name, size: 1}
    assert stop == Map.merge(start, %{result: :ok, reason: nil, batch_id: @batch})

    assert {start, stop} = span(:workflow)
    assert start == %{instance: name, call: :signal, name: "approve"}
    assert stop == Map.merge(start, %{result: :ok, reason: nil})

    {:messages, messages} = Process.info(self(), :messages)

    for secret <- ["tenant-secret", "run-secret-1", "payload-secret", "t0ken"] do
      refute inspect(messages) =~ secret
    end
  end

  test "an exception carries the start's metadata, the kind and the class only", %{name: name} do
    assert_raise ArgumentError, fn -> JoobQ.rate_limit("tenant-secret", 0, 1, name: name) end

    assert_raise ArgumentError, fn ->
      JoobQ.update_workflow("run-secret-1", "set", nil, name: name, wait_ms: 1)
    end

    assert_received {:event, [:joobq, :rate_limit, :exception], limit}
    failed = %{kind: :error, error_class: "ArgumentError"}
    assert limit == Map.merge(%{instance: name, limit: 0, period_ms: 1}, failed)
    assert_received {:event, [:joobq, :workflow, :exception], update}
    assert update == Map.merge(%{instance: name, call: :update, name: "set"}, failed)
    refute inspect({limit, update}) =~ "secret"
  end
end
